def reconcile_read_only(records, expected=EXPECTED):
    """Read fixture dictionaries only. This function performs no API or side effect."""
    try:
        operation = records["operation"]
        status = records["status"]
        inventory = records["inventory"]

        required_operation = {
            "operation_id": expected["operation_id"],
            "event_id": expected["event_id"],
            "action": expected["action"],
            "requested_quantity": expected["quantity"],
            "idempotency_key": expected["idempotency_key"],
        }
        if any(operation.get(k) != v for k, v in required_operation.items()):
            return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}

        if status.get("operation_id") != expected["operation_id"]:
            return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}

        if inventory.get("event_id") != expected["event_id"]:
            return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}
        if inventory.get("item") != expected["item"]:
            return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}

        if status.get("status") == "SUCCEEDED":
            if inventory.get("reserved") != expected["quantity"]:
                return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}
            if status.get("postcondition") != expected["postcondition"]:
                return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}
            return {
                "result": "timeout-success",
                "next_action": "stop",
                "observable_postcondition": status["postcondition"],
            }

        if status.get("status") in {"PENDING", "UNKNOWN"}:
            return {
                "result": "unknown-or-pending",
                "next_action": "one later read-only status check; no replay",
            }

        if status.get("status") == "TERMINAL_FAILURE":
            return {
                "result": "terminal-failure",
                "next_action": "escalate; no replay without separate authorization",
            }

        return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}
    except (AttributeError, KeyError, TypeError):
        return {"result": "unresolved-or-escalate", "next_action": "escalate; no replay"}


CASES = [
    ("SUCCESS", SUCCESS, "timeout-success"),
    ("PENDING", PENDING, "unknown-or-pending"),
    ("UNKNOWN", UNKNOWN, "unknown-or-pending"),
    ("INCONSISTENT", INCONSISTENT, "unresolved-or-escalate"),
    ("MISSING_FIELD", MISSING_FIELD, "unresolved-or-escalate"),
    ("MISMATCHED_PENDING", MISMATCHED_PENDING, "unresolved-or-escalate"),
    ("TERMINAL_FAILURE", TERMINAL_FAILURE, "terminal-failure"),
]


for name, records, expected_result in CASES:
    result = reconcile_read_only(records)
    assert result["result"] == expected_result, (name, result)
    print(name + ": " + json.dumps(result, sort_keys=True))

