assert reconcile_read_only(MISSING_FIELD)["next_action"] == "escalate; no replay"
assert reconcile_read_only(MISMATCHED_PENDING)["next_action"] == "escalate; no replay"
assert not any(name == "side_effect" for name, value in globals().items())
print("ALL ASSERTIONS PASSED")

